cd ~/Developer/Perso/homelab; TOK=$(awk '/machine git.daddyshome.fr/{print $6}' ~/.netrc); sha=d421b1a1c83debbd34c4af618674eeca3ca02d33; poll(){ curl -sS --max-time 30 --cert ~/.config/mtls/daddyshome-client.crt --key *** -H "Authorization: token $TOK" "https://git.daddyshome.fr/api/v1/repos/fredericrous/homelab/commits/$sha/statuses?limit=100" | python3 -I -c '
import sys,json
try: rows=json.load(sys.stdin)
except Exception: print("read error"); sys.exit(1)
T={"success","failure","error","skipped"}; best={}
for r in rows:
    c,s=r["context"],r["status"]
    if c not in best or (best[c] not in T and s in T): best[c]=s
pend=[c for c,s in best.items() if s not in T]; bad=[c for c,s in best.items() if s in ("failure","error")]
print(len(best),"checks; pending:",len(pend),"failed:",bad)
sys.exit(0 if best and not pend else 1)'; }; end=$((SECONDS+2400)); sleep 30; until poll || [ $SECONDS -ge $end ]; do sleep 45; done; if [ $SECONDS -ge $end ]; then echo TIMEOUT; fi; true
